cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('tests/multiline.rs')
text = path.read_text()
assert 'replacement_named_capture' not in text
text += r'''
rgtest!(replacement_named_capture, |dir: Dir, mut cmd: TestCommand| {
    let mut input = String::from(
        "# First documentation line.\n\
         # Second documentation line.\n\
         pipc () {  # usage\n",
    );
    input.push_str(&"    body\n".repeat(32));
    dir.create("test", &input);
    cmd.args(&[
        "-NU",
        "-r",
        "$usage",
        r#"^(?P<predoc>\n?(# .*\n)*)(alias (?P<aname>pipc)="[^"]+"|(?P<fname>pipc) \(\) \{)(  #(?P<usage> .+))?"#,
        "test",
    ]);
    eqnice!(" usage\n", cmd.stdout());
});

rgtest!(replacement_boundaries, |dir: Dir, mut cmd: TestCommand| {
    dir.create(
        "test",
        "prefix\nbefore\nfoo bar suffix\nmiddle\nbefore\nfoo baz suffix\nafter\n",
    );
    cmd.args(&[
        "-NU",
        "-r",
        "$last",
        r"before\nfoo (?P<last>\w+)",
        "test",
    ]);
    eqnice!("bar suffix\nbaz suffix\n", cmd.stdout());
});

rgtest!(replacement_context, |dir: Dir, mut cmd: TestCommand| {
    dir.create("test", "prefix\nbefore\nfoo bar\nafter\n");
    cmd.args(&[
        "-nU",
        "-C1",
        "-r",
        "$last",
        r"before\nfoo (?P<last>.+)",
        "test",
    ]);
    eqnice!("1-prefix\n2:bar\n4-after\n", cmd.stdout());
});

rgtest!(replacement_look_around, |dir: Dir, mut cmd: TestCommand| {
    if !dir.is_pcre2() {
        return;
    }
    dir.create("test", "prefix\nbefore\nfoo bar\nafter\n");
    cmd.args(&[
        "-NU",
        "-r",
        "$last",
        r"(?<=prefix\n)before\nfoo (?P<last>\w+)(?=\nafter)",
        "test",
    ]);
    eqnice!("bar\n", cmd.stdout());
});
'''
path.write_text(text)
PY
RUSTFLAGS=-Awarnings cargo test --package ripgrep --test integration -- multiline::replacement

cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('crates/printer/src/util.rs')
text = path.read_text()
old = '''    /// Executes a replacement on the given subject string by replacing all
    /// matches with the given replacement. To access the result of the
    /// replacement, use the `replacement` method.
'''
new = '''    /// Executes a replacement on matches in the given range of the subject.
    /// Bytes outside the range are used only for matching context, and are not
    /// included in the result. To access the result of the replacement, use
    /// the `replacement` method.
'''
assert text.count(old) == 1
text = text.replace(old, new)
old = '''            matcher
                .replace_with_captures_at(
                    subject,
                    range.start,
                    caps,
                    dst,
                    |caps, dst| {
                        let start = dst.len();
                        caps.interpolate(
                            |name| matcher.capture_index(name),
                            subject,
                            replacement,
                            dst,
                        );
                        let end = dst.len();
                        matches.push(Match::new(start, end));
                        true
                    },
                )
                .map_err(io::Error::error_message)?;
'''
new = '''            let mut last_match = range.start;
            matcher
                .captures_iter_at(subject, range.start, caps, |caps| {
                    let m = caps.get(0).unwrap();
                    if is_multi_line && m.start() >= range.end {
                        return false;
                    }
                    dst.extend_from_slice(&subject[last_match..m.start()]);
                    last_match = m.end();
                    let start = dst.len();
                    caps.interpolate(
                        |name| matcher.capture_index(name),
                        subject,
                        replacement,
                        dst,
                    );
                    let end = dst.len();
                    matches.push(Match::new(start, end));
                    true
                })
                .map_err(io::Error::error_message)?;
            let end = range.end.min(subject.len());
            if last_match < end {
                dst.extend_from_slice(&subject[last_match..end]);
            }
'''
assert text.count(old) == 1
path.write_text(text.replace(old, new))
path = Path('CHANGELOG.md')
text = path.read_text()
old = '''  Disable mmap searching in all non-64-bit environments.
'''
new = old + '''* Fix multiline replacements leaking content beyond the matching lines.
'''
assert text.count(old) == 1
path.write_text(text.replace(old, new))
PY
RUSTFLAGS=-Awarnings cargo test --package ripgrep --test integration -- multiline::replacement

